<style>
    :root {
        --gold-color: #8A7A5C;
        --text-dark: #111;
        --text-gray: #777;
    }

    body {
        margin: 0;
        padding: 40px 20px;
        background-color: #f4f4f4;
        display: flex;
        justify-content: center;
        font-family: "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Helvetica, Arial, sans-serif;
    }

    .poster-container {
        width: 750px;
        background-color: #ffffff;
        padding: 50px;
        box-sizing: border-box;
        box-shadow: 0 10px 30px rgba(0,0,0,0.1);
        position: relative;
    }

    /* Top Section */
    .top-section {
        margin-bottom: 20px;
    }

    .main-title {
        font-size: 72px;
        font-weight: 900;
        color: var(--text-dark);
        margin: 0;
        line-height: 1;
        text-align: justify;
        text-align-last: justify;
        letter-spacing: -2px;
    }

    .subtitle-row {
        display: flex;
        align-items: center;
        margin-top: 15px;
        font-size: 11px;
        font-weight: bold;
        color: var(--text-dark);
        letter-spacing: 1px;
    }

    .subtitle-text {
        font-family: "Arial", sans-serif;
    }

    .subtitle-line {
        flex-grow: 1;
        height: 1px;
        background-color: var(--text-dark);
        position: relative;
        margin: 0 10px;
    }

    .subtitle-line::before {
        content: '•';
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translate(-50%, -50%);
        background-color: #fff;
        padding: 0 4px;
        font-size: 16px;
        line-height: 1;
    }

    .subtitle-line.arrow-line::before {
        content: '▶';
        font-size: 8px;
        padding: 0 2px;
    }

    .subtitle-icon {
        font-size: 18px;
        line-height: 1;
    }

    /* Graphic Placeholder */
    .graphic-placeholder {
        width: 100%;
        height: 400px;
        background: linear-gradient(135deg, #fdfdfd 0%, #ebebeb 100%);
        border: 1px dashed #ccc;
        display: flex;
        align-items: center;
        justify-content: center;
        color: #999;
        font-style: italic;
        margin: 30px 0;
        box-sizing: border-box;
    }

