        left: 0;
        bottom: 0;
        font-size: 9px;
        font-weight: bold;
        line-height: 1.8;
        color: var(--text-dark);
    }

    .list-right {
        position: absolute;
        right: 0;
        bottom: 10px;
        font-size: 12px;
        font-weight: bold;
        line-height: 2;
        text-align: right;
        color: var(--text-dark);
