        color: var(--gold-color);
        text-align: center;
        line-height: 0.85;
    }

    .col-arts .arts {
        font-size: 28px;
        letter-spacing: 1px;
    }

    .col-arts .chinese {
        font-size: 34px;
        font-weight: normal;
    }

