        flex-direction: column;
        align-items: center;
        width: 70px;
    }

    .role-title {
        font-size: 12px;
        font-weight: bold;
        margin-bottom: 10px;
        display: flex;
        align-items: center;
        gap: 4px;
        white-space: nowrap;
    }

    .role-title::before {
        content: '•';
        font-size: 10px;
    }

    .name-list {
        display: flex;
        flex-direction: column;
        gap: 6px;
        font-size: 16px;
        font-weight: bold;
        text-align: center;
    }

    /* Artists Bottom Left */
    .artists-group {
        position: absolute;
        left: 0;
        top: 150px;
        display: flex;
        align-items: flex-start;
    }

    .artists-label {
        writing-mode: vertical-rl;
        font-size: 20px;
        font-weight: bold;
        letter-spacing: 15px;
        margin-right: 25px;
        margin-top: 5px;
    }

    .artists-list-container {
        display: flex;
        flex-direction: row;
        gap: 16px;
    }

    .artist-item {
        display: flex;
        flex-direction: column;
        align-items: center;
    }

    .artist-item .zh-name {
        writing-mode: vertical-rl;
        font-size: 13px;
        font-weight: bold;
        letter-spacing: 2px;
    }

    .artist-item .py-name {
        writing-mode: vertical-rl;
        text-orientation: sideways;
        font-size: 9px;
        font-family: Arial, sans-serif;
        color: #444;
